async def main():
    async with Painter() as p:
        await p.key('Escape')
        await p.tool('brush')
        await p.size(2)
        for name,points in paths:
            await p.drag(points)
            print('Mouse strokes:',name,flush=True)
        await p.shot('stage1-outlines.png')
asyncio.run(main())
